let fish;

function setup() {
  createCanvas(400, 400);
  fish = new Fish();
}

function draw() {
  background(220);
  fish.update();
  fish.display();
}

class Fish {
  constructor() {
    this.x = width / 2;
    this.y = height / 2;
    this.speed = 5;
  }

  update() {
    let targetX = mouseX;
    let targetY = mouseY;

    let dx = targetX - this.x;
    let dy = targetY - this.y;
    let distance = dist(this.x, this.y, targetX, targetY);

    if (distance > 1) {
      this.x += (dx / distance) * this.speed;
      this.y += (dy / distance) * this.speed;
    }
  }

  display() {
    fill(0, 191, 255); // Blue color for fish
    noStroke();
    ellipse(this.x, this.y, 40, 20); // Fish body
    triangle(
      this.x - 20, this.y,
      this.x - 30, this.y - 10,
      this.x - 30, this.y + 10
    ); // Fish tail
  }
}

