let fishX, fishY, fishSpeed;

function initializeFish() {
  fishX = width / 2;
  fishY = height / 2;
  fishSpeed = 5;
}

function updateFish() {
  let targetX = mouseX;
  let targetY = mouseY;

  let dx = targetX - fishX;
  let dy = targetY - fishY;
  let distance = dist(fishX, fishY, targetX, targetY);

  if (distance > 1) {
    fishX += (dx / distance) * fishSpeed;
    fishY += (dy / distance) * fishSpeed;
  }
}

function displayFish() {
  fill(0, 191, 255); // Blue color for fish
  noStroke();
  ellipse(fishX, fishY, 40, 20); // Fish body
  triangle(
    fishX - 20, fishY,
    fishX - 30, fishY - 10,
    fishX - 30, fishY + 10
  );
}

